const staffParameters=['emp code','name','user type','center code','city','state','status'];
const vendorParameters=['vendor code','vendor name','vendor type','employment type','gst type','service type','oracle id','status'];
const mappingRows=[
['Last Mile','Rider','HRMS, FAAS','Any last mile dispatcher whom we want to pay. These include: LMAs, On rolls, OFRs'],
['Last Mile','TL','HRMS, FAAS','TL and ATL mapped to the centers whom we want to pay.'],
['Hyperlocal','Driver','HRMS, FAAS','Any hyperlocal driver whom we want to pay. These include: Agents, On rolls, OFRs'],
['Rapid','Rider','HRMS, FAAS','Any rapid riders whom we want to pay. These include: Agents, On rolls, OFRs'],
['First Mile','Rider','HRMS, FAAS','Any first mile dispatcher whom we want to pay. These include: On rolls, OFRs'],
['Returns','Rider','HRMS, FAAS','Any first mile dispatcher whom we want to pay. These include: On rolls, OFRs'],
['First Mile','Vendor','Vendor DB',"Any last mile vendor whom we want to pay, based on vendor's performance, not on any lower grain, i.e. manpower under them."],
['Returns','Vendor','Vendor DB',"Any last mile vendor whom we want to pay, based on vendor's performance, not on any lower grain, i.e. manpower under them."],
['Last Mile','Vendor','Vendor DB',"Any last mile vendor whom we want to pay, based on vendor's performance, not on any lower grain, i.e. manpower under them."]];
let entityMappings=mappingRows.map((r,i)=>({id:'mapping-'+i,lob:r[0],entity:r[1],source:r[2],description:r[3],enabled:true,parameters:(r[1]==='Vendor'?vendorParameters:staffParameters).map((name,j)=>({name,type:'Character',included:true,filter:true,identity:j===0}))}));
let mappingDraft=null;
const parameterLabel=s=>s.replace(/\b\w/g,c=>c.toUpperCase());
const techBaseNav=navRole;
navRole=function(){techBaseNav();const select=document.getElementById('role');const option=document.createElement('option');option.value='tech';option.textContent='Tech / Product';select.prepend(option);select.value=role;select.onchange=e=>{role=e.target.value;currentView=role==='admin'?'registry':role;mappingDraft=null;render()};if(role==='tech')document.querySelector('.admin').innerHTML='Tech / Product<small>Entity data whitelist</small>';else document.querySelector('.admin').innerHTML=esc(role[0].toUpperCase()+role.slice(1))+' workspace<small>Last Mile · Rider</small>'};
const techBaseRender=render;
render=function(){if(role!=='tech'){techBaseRender();return}navRole();document.getElementById('breadcrumb').textContent='Tech / Product / Entity data';document.getElementById('app').innerHTML=mappingDraft?mappingEditor():mappingList();bindMappings()};
function mappingList(){return `<div class="titlebar"><h1>Entity data whitelist ${info('Approve Business Line, Entity and source mappings. Choose the associated data and filters available to Admins.')}</h1><span class="badge">${entityMappings.filter(m=>m.enabled).length} of ${entityMappings.length} whitelisted</span></div><section class="panel"><div class="panel-head"><h2>Business Line ↔ Entity ↔ Data</h2><span class="quiet">Tech / Product</span></div><div class="tablewrap"><table class="mapping-table"><thead><tr><th>BUSINESS LINE</th><th>ENTITY</th><th>PARAMETERS ${info('Entity attributes supplied by the mapped source.')}</th><th>STATUS</th><th></th></tr></thead><tbody>${entityMappings.map(m=>`<tr><td><strong>${esc(m.lob)}</strong></td><td>${esc(m.entity)}</td><td>${m.parameters.filter(p=>p.included).map(p=>`<span class="tag">${esc(p.name)}</span>`).join('')}<small>${m.parameters.filter(p=>p.included&&p.filter).length} entity filters</small></td><td><span class="tag ${m.enabled?'status-live':'status-draft'}">${m.enabled?'Whitelisted':'Not whitelisted'}</span></td><td><button class="link" data-mapping="${m.id}">Configure</button></td></tr>`).join('')}</tbody></table></div></section><p class="footer">Sample prototype · Changes last for this page session.</p>`}
function mappingEditor(){const m=mappingDraft;return `<div class="titlebar"><div><button class="link" id="mappingBack">Entity data whitelist</button><h1 style="margin-top:12px">${esc(m.lob)} / ${esc(m.entity)}</h1></div></div><div class="split"><div><section class="panel"><div class="panel-head"><h2>Entity mapping</h2></div><div class="panel-body"><div class="grid group"><div><span class="eyebrow">BUSINESS LINE</span><strong>${esc(m.lob)}</strong></div><div><span class="eyebrow">ENTITY</span><strong>${esc(m.entity)}</strong></div></div><div class="group"><span class="eyebrow">DESCRIPTION</span><p class="mapping-description">${esc(m.description)}</p></div><label class="choice"><input type="checkbox" id="mappingEnabled" ${m.enabled?'checked':''}>Whitelist this mapping ${info('Make this Business Line, Entity and source combination available for configuration.')}</label></div></section><section class="panel"><div class="panel-head"><h2>Entity parameters</h2><span class="quiet">${m.parameters.length} parameters</span></div><div class="tablewrap"><table><thead><tr><th>PARAMETER</th><th>DATA TYPE ${info('Character data includes codes and identifiers, even when a code contains only digits.')}</th><th>INCLUDE ${info('Make this attribute available as entity data. The identifier is required.')}</th><th>ENTITY FILTER ${info('Allow Admins to expose this attribute as a participant filter. The attribute must be included in the entity data.')}</th></tr></thead><tbody>${m.parameters.map((p,i)=>`<tr><td><strong>${esc(p.name)}</strong>${p.identity?'<small>Entity identifier</small>':''}</td><td>Character</td><td><input type="checkbox" data-parameter-include="${i}" aria-label="Include ${esc(p.name)}" ${p.included?'checked':''} ${p.identity?'disabled':''}></td><td><input type="checkbox" data-parameter-filter="${i}" aria-label="Whitelist ${esc(p.name)} as a filter" ${p.filter?'checked':''} ${!p.included?'disabled':''}></td></tr>`).join('')}</tbody></table></div></section><div class="savebar"><button class="button" id="mappingReset">Reset</button><button class="button primary" id="mappingSave">Save whitelist</button></div></div><section class="panel summary"><div class="panel-head"><h2>Admin availability</h2></div><div class="panel-body"><dl><dt>MAPPING</dt><dd>${m.enabled?esc(m.lob)+' / '+esc(m.entity):'Not whitelisted'}</dd><dt>ENTITY DATA</dt><dd>${m.enabled?m.parameters.filter(p=>p.included).map(p=>esc(p.name)).join(', '):'Unavailable'}</dd><dt>ENTITY FILTERS</dt><dd>${m.enabled?m.parameters.filter(p=>p.included&&p.filter).map(p=>esc(p.name)).join(', ')||'None':'Unavailable'}</dd></dl></div></section></div><p class="footer">Sample prototype · Changes last for this page session.</p>`}
function updateMappingParameter(index,kind,checked){const p=mappingDraft.parameters[index];if(kind==='included'){if(p.identity&&!checked)return;p.included=checked;if(!checked)p.filter=false}else p.filter=p.included&&checked}
function bindMappings(){document.querySelectorAll('[data-mapping]').forEach(b=>b.onclick=()=>{mappingDraft=structuredClone(entityMappings.find(m=>m.id===b.dataset.mapping));render()});document.getElementById('mappingBack')?.addEventListener('click',()=>{mappingDraft=null;render()});document.getElementById('mappingEnabled')?.addEventListener('change',e=>{mappingDraft.enabled=e.target.checked;render()});document.querySelectorAll('[data-parameter-include]').forEach(el=>el.onchange=()=>{updateMappingParameter(Number(el.dataset.parameterInclude),'included',el.checked);render()});document.querySelectorAll('[data-parameter-filter]').forEach(el=>el.onchange=()=>{updateMappingParameter(Number(el.dataset.parameterFilter),'filter',el.checked);render()});document.getElementById('mappingReset')?.addEventListener('click',()=>{mappingDraft=structuredClone(entityMappings.find(m=>m.id===mappingDraft.id));render()});document.getElementById('mappingSave')?.addEventListener('click',saveMapping)}
function saveMapping(){const index=entityMappings.findIndex(m=>m.id===mappingDraft.id);entityMappings[index]=structuredClone(mappingDraft);syncRiderWhitelist();mappingDraft=null;render();toast('Entity data whitelist saved for this session.');return true}
// Existing incentive examples use the Last Mile / Rider mapping.
function riderMapping(){return entityMappings[0]}
const legacyLabels={'Entity ID':'Emp Code',Center:'Center Code'};
function syncRiderWhitelist(){const m=riderMapping();const allowed=m.enabled?m.parameters.filter(p=>p.included&&p.filter).map(p=>parameterLabel(p.name)):[];entityKeys.splice(0,entityKeys.length,...allowed);configs.forEach(c=>{c.entities=c.entities.map(k=>legacyLabels[k]||k).filter(k=>allowed.includes(k))});if(selected>=0&&configs[selected])draft=structuredClone(configs[selected])}
entityValues['Emp Code']=['RDR-1041','RDR-1042','RDR-1043'];entityValues.Name=['Amit Kumar','Rahul Sharma','Priya Singh'];entityValues['Center Code']=['BLR-HSR','BLR-Whitefield'];entityValues.State=['Karnataka','Telangana'];entityValues['User Type']=['LMA','On rolls','OFR'];Object.assign(previewEntity,{'Emp Code':'RDR-1041',Name:'Amit Kumar','Center Code':'BLR-HSR',State:'Karnataka','User Type':'LMA'});
configs.forEach(c=>c.entities=staffParameters.map(parameterLabel));programs.forEach(p=>{const rules=ensureRules(p);rules.entityFilters=rules.entityFilters.filter(r=>r.field!=='Zone').map(r=>({...r,field:legacyLabels[r.field]||r.field}))});syncRiderWhitelist();
context=function(){const m=riderMapping();return `<div class="context"><div><span class="eyebrow">BUSINESS LINE</span><strong>${esc(m.lob)}</strong></div><div><span class="eyebrow">ENTITY</span><strong>${esc(m.entity)}</strong></div><div><span class="eyebrow">SOURCE</span><strong>${esc(m.source)}</strong></div><div class="right"><span class="eyebrow">WHITELISTED ENTITY FILTERS ${info('Configured in the Tech / Product view for this mapping.')}</span><strong>${entityKeys.map(esc).join(' · ')||'None'}</strong></div></div>`};
const baseTechRegistry=registry,baseTechConfig=configView,baseTechManagerForm=managerForm;
function mappingUnavailable(){return `<div class="titlebar"><h1>Last Mile / Rider</h1></div><div class="panel"><div class="panel-body">This entity mapping is not whitelisted. Enable it in Tech / Product to configure incentives.</div></div>`}
registry=function(){return riderMapping().enabled?baseTechRegistry().replaceAll('Delivery / Rider','Last Mile / Rider'):mappingUnavailable()};
configView=function(){return riderMapping().enabled?baseTechConfig():mappingUnavailable()};
managerForm=function(){return riderMapping().enabled?baseTechManagerForm().replaceAll('Delivery / Rider','Last Mile / Rider'):mappingUnavailable()};
const oldBlankTech=blankProgram;blankProgram=function(type=0){const p=oldBlankTech(type);p.entityMappingId=riderMapping().id;return p};
role='tech';currentView='tech';render();
if(document.modelContext?.registerTool){try{Promise.resolve(document.modelContext.registerTool({name:'read_entity_whitelist',description:'Read the current sample Business Line, Entity, source and parameter whitelist.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute:()=>structuredClone(entityMappings)})).catch(()=>{})}catch{}}
